<template>
  <div class="ts-flip-stage" :class="{ flipping: isFlipping }">
    <div class="ts-wrap">
      <div class="ts-panel">
        <div class="ts-header-row">
          <div class="ts-header-left">
            <button
              v-if="mode === 'type'"
              class="ts-flip"
              @click="$emit('open-form')"
            >
              <v-icon icon="mdi-form-select" size="16" />
              Custom Query
            </button>
          </div>

          <div class="ts-header-center">
            <h2 class="ts-title">
              {{ mode === "type" ? "New Dashboard" : "My Saved Dashboards" }}
            </h2>

            <div class="ts-subtitle">
              {{
                mode === "type"
                  ? "Choose a type to start a new dashboard"
                  : "Pick a dashboard you saved before"
              }}
            </div>
          </div>

          <div class="ts-header-right">
            <button
              class="ts-flip"
              :class="{ flipping: isFlipping }"
              :title="
                mode === 'type' ? 'Show saved dashboards' : 'Show object types'
              "
              @click="flipMode"
            >
              <v-icon
                class="ts-flip-icon"
                :icon="
                  mode === 'type'
                    ? 'mdi-content-save-outline'
                    : 'mdi-view-grid-outline'
                "
                size="16"
              />
              {{ mode === "type" ? "Saved Dashboards" : "Object Types" }}
            </button>
          </div>
        </div>
        <div class="ts-search">
          <v-text-field
            v-model="search"
            prepend-inner-icon="mdi-magnify"
            :placeholder="
              mode === 'type' ? text.searchPlaceholder : 'Search dashboards...'
            "
            variant="outlined"
            density="comfortable"
            hide-details
            class="mx-auto mb-6"
            style="max-width: 360px"
          />
        </div>

        <div v-if="mode === 'type'" class="ts-card-container">
          <!-- First 8 -->
          <div class="ts-grid-featured">
            <div
              v-for="type in filteredTypes.slice(0, 8)"
              :key="type.name"
              class="ts-card featured"
              :style="
                selected === type.name ? activeCardStyle : inactiveCardStyle
              "
              @click="selectType(type.name)"
            >
              <div
                class="ts-badge"
                :style="{
                  background:
                    selected === type.name ? BRAND.primary : '#EEEEEE',
                }"
              >
                <v-icon
                  :icon="type.icon"
                  size="20"
                  :style="{ color: selected === type.name ? '#FFF' : '#555' }"
                />
              </div>

              <div
                class="ts-card-label"
                :style="{
                  color: selected === type.name ? BRAND.primary : '#333',
                }"
              >
                {{ type.name }}
              </div>
            </div>
          </div>

          <!-- Remaining -->
          <div v-if="filteredTypes.length > 8" class="ts-grid-compact">
            <div
              v-for="type in filteredTypes.slice(8)"
              :key="'small-' + type.name"
              class="ts-card compact"
              :style="
                selected === type.name ? activeCardStyle : inactiveCardStyle
              "
              @click="selectType(type.name)"
            >
              <div
                class="ts-badge"
                :style="{
                  background:
                    selected === type.name ? BRAND.primary : '#EEEEEE',
                }"
              >
                <v-icon
                  :icon="type.icon"
                  size="16"
                  :style="{ color: selected === type.name ? '#FFF' : '#555' }"
                />
              </div>

              <div
                class="ts-card-label"
                :style="{
                  color: selected === type.name ? BRAND.primary : '#333',
                }"
              >
                {{ type.name }}
              </div>
            </div>
          </div>
        </div>

        <div v-else class="ts-card-container">
          <!-- <div v-if="!filteredSavedViews.length" class="ts-empty">
            No other saved dashboards yet.
          </div> -->

          <!-- First 8 (default card is always first) -->
          <div class="ts-grid-featured">
            <div
              class="ts-card featured"
              :style="inactiveCardStyle"
              @click="showDefault = true"
            >
              <div class="ts-badge" style="background: #eeeeee">
                <v-icon
                  icon="mdi-star-circle-outline"
                  size="20"
                  style="color: #555"
                />
              </div>
              <span class="ts-system-badge">Default</span>
              <div class="ts-card-label" style="color: #333">
                Projects by Sub Type
              </div>
            </div>

            <div
              v-for="v in filteredSavedViews.slice(0, 7)"
              :key="v.id"
              class="ts-card featured"
              :style="
                selectedView === v.id ? activeCardStyle : inactiveCardStyle
              "
              @click="selectSavedView(v.id)"
            >
              <div
                class="ts-badge"
                :style="{
                  background: selectedView === v.id ? BRAND.primary : '#EEEEEE',
                }"
              >
                <v-icon
                  icon="mdi-view-dashboard-outline"
                  size="20"
                  :style="{ color: selectedView === v.id ? '#FFF' : '#555' }"
                />
              </div>
              <span v-if="v.isSystem" class="ts-system-badge">System</span>

              <div
                class="ts-card-label"
                :style="{
                  color: selectedView === v.id ? BRAND.primary : '#333',
                }"
              >
                {{ v.name }}
              </div>
            </div>
          </div>

          <!-- Remaining -->
          <div v-if="filteredSavedViews.length > 7" class="ts-grid-compact">
            <div
              v-for="v in filteredSavedViews.slice(7)"
              :key="'small-' + v.id"
              class="ts-card compact"
              :style="
                selectedView === v.id ? activeCardStyle : inactiveCardStyle
              "
              @click="selectSavedView(v.id)"
            >
              <div
                class="ts-badge"
                :style="{
                  background: selectedView === v.id ? BRAND.primary : '#EEEEEE',
                }"
              >
                <v-icon
                  icon="mdi-view-dashboard-outline"
                  size="16"
                  :style="{ color: selectedView === v.id ? '#FFF' : '#555' }"
                />
              </div>
              <span v-if="v.isSystem" class="ts-system-badge">System</span>

              <div
                class="ts-card-label"
                :style="{
                  color: selectedView === v.id ? BRAND.primary : '#333',
                }"
              >
                {{ v.name }}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <DefaultDashboardDialog
      v-model="showDefault"
      :loading="busy"
      @submit="openDefault"
    />
  </div>
</template>

<script>
import { TYPE_SELECTION_TEXT } from "@/utils/uiText";
import { useDashboardStore } from "@/store/dashboardStore";
import savedViewsApi from "@/services/savedViewsApi";
import dashboardApi from "@/services/dashboardApi";
import { toastBus } from "@/components/common/toastBus";
import DefaultDashboardDialog from "@/components/dashboard/DefaultDashboardDialog.vue";

const BRAND = { primary: "#0F62FE" };

export default {
  name: "TypeSelectionView",

  components: { DefaultDashboardDialog },

  emits: ["open-dashboard", "open-saved-view", "open-form"],

  setup() {
    return { store: useDashboardStore() };
  },

  data() {
    return {
      mode: "saved",
      isFlipping: false,
      savedViews: [],
      selectedView: null,
      BRAND,
      text: TYPE_SELECTION_TEXT,
      search: "",
      selected: this.store.type,
      showDefault: false,
      busy: false,
    };
  },

  computed: {
    types() {
      return this.store.getTypeOptions;
    },
    filteredTypes() {
      const q = this.search.trim().toLowerCase();
      if (!q) return this.types;
      return this.types.filter((t) => t.name.toLowerCase().includes(q));
    },
    activeCardStyle() {
      return {
        border: `1.5px solid ${BRAND.primary}`,
        background: "rgba(15,98,254,0.06)",
      };
    },
    inactiveCardStyle() {
      return { border: "1px solid #DDDDDD", background: "#FFFFFF" };
    },
    filteredSavedViews() {
      const q = this.search.trim().toLowerCase();

      if (!q) {
        return this.savedViews;
      }

      return this.savedViews.filter((view) =>
        view.name.toLowerCase().includes(q)
      );
    },
  },

  async mounted() {
    if (this.mode === "saved") await this.loadSavedViews();
  },

  methods: {
    async loadSavedViews() {
      const all = await savedViewsApi.getSavedViews();
      const user = this.store.getUser;
      const me = user?.firstName + " " + user?.lastName;
      this.savedViews = [...all.filter((v) => v.createdBy === me)];
    },
    selectType(name) {
      this.selected = name;
      this.openDashboard();
    },
    selectSavedView(id) {
      this.selectedView = id;
      const view = this.savedViews.find((v) => v.id === id);
      if (view) this.$emit("open-saved-view", view);
    },
    async flipMode() {
      this.isFlipping = true;
      setTimeout(() => {
        this.isFlipping = false;
      }, 500);
      this.mode = this.mode === "type" ? "saved" : "type";
      if (this.mode === "saved" && !this.savedViews.length) {
        await this.loadSavedViews();
      }
    },
    openDashboard() {
      this.store.setType(this.selected);
      this.$emit("open-dashboard", {});
    },
    async openDefault(form) {
      this.busy = true;
      try {
        this.store.setCustomForm(null); // old form must not affect the sub object search
        const { names, ids } = await dashboardApi.fetchProjectNamesBySubObject(form);
        if (!names.length && !ids.length) {
          return toastBus.emit("No projects found.", "error");
        }
        this.store.setType("Project");
        this.store.setCustomForm({ projectNames: names, projectIds: ids });
        this.showDefault = false;
        this.$emit("open-dashboard", {});
      } catch (e) {
        toastBus.emit("Failed to load projects.", "error");
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.ts-wrap {
  min-height: calc(100vh - 20px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  box-sizing: border-box;
}
.ts-panel {
  width: 100%;
  max-width: 760px;
  height: 90vh;
  background: #fff;
  border: 1px solid #e0e0e0;
  border-radius: 12px;
  padding: 28px 32px;
  box-sizing: border-box;

  display: flex;
  flex-direction: column;
}
.ts-search {
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}
.ts-header-row {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  margin-bottom: 24px;
}
.ts-header-left {
  display: flex;
  justify-content: flex-start;
  align-items: center;
}
.ts-header-center {
  text-align: center;
}
.ts-header-right {
  display: flex;
  justify-content: flex-end;
  align-items: center;
}
.ts-flip {
  display: flex;
  align-items: center;
  gap: 4px;
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 12px;
  color: #444;
  background: #fff;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease, border-color 0.15s ease,
    transform 0.1s ease;
}
.ts-flip:hover {
  background: #f5f7fa;
  border-color: #bbb;
}
.ts-flip:active {
  transform: scale(0.96);
}
.ts-flip-icon {
  transition: transform 0.35s ease;
}
.ts-flip.flipping .ts-flip-icon {
  transform: rotateY(180deg);
}
.ts-flip-stage {
  perspective: 1200px;
}
.ts-flip-stage.flipping {
  animation: ts-page-flip 0.5s ease;
  transform-style: preserve-3d;
}
@keyframes ts-page-flip {
  0% {
    transform: rotateY(0deg);
    opacity: 1;
  }
  50% {
    transform: rotateY(90deg);
    opacity: 0.3;
  }
  100% {
    transform: rotateY(0deg);
    opacity: 1;
  }
}
.ts-empty {
  grid-column: 1 / -1;
  text-align: center;
  color: #999;
  font-size: 13px;
  padding: 20px;
}
.ts-title {
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 4px;
  color: #1a1a1a;
}
.ts-subtitle {
  font-size: 13px;
  color: #666666;
}
.ts-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.ts-grid-featured {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 18px;
}

.ts-grid-compact {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
}

.ts-card.featured {
  min-height: 110px;
}

.ts-card.compact {
  min-height: 75px;
  padding: 10px 4px;
}

.ts-card.compact .ts-badge {
  width: 28px;
  height: 28px;
}

.ts-card.compact .ts-card-label {
  font-size: 11px;
}

.ts-card.compact .v-icon {
  font-size: 16px;
}
.ts-card {
  position: relative;
  border-radius: 10px;
  padding: 18px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  box-sizing: border-box;
}
.ts-system-badge {
  position: absolute;
  top: 6px;
  right: 6px;
  font-size: 10px;
  font-weight: 600;
  color: #0f62fe;
  background: #e8f0fe;
  border-radius: 4px;
  padding: 2px 6px;
}
.ts-badge {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ts-card-label {
  font-size: 13px;
  text-align: center;
}
@media (max-width: 600px) {
  .ts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .ts-wrap {
    padding: 12px;
  }
}
.ts-card-container {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 6px;
}
.ts-card-container::-webkit-scrollbar {
  width: 8px;
}

.ts-card-container::-webkit-scrollbar-thumb {
  background: #c8c8c8;
  border-radius: 4px;
}

.ts-card-container::-webkit-scrollbar-thumb:hover {
  background: #999;
}
</style>