import { defineStore } from "pinia";
import { DEFAULT_TYPE, DEFAULT_VIEW_SETTINGS } from "@/utils/dashboardData";
import typeConfigApi from "@/services/typeConfigApi";

const FALLBACK_TYPE_CONFIG = [
  { name: "Engineering", icon: "mdi-cube-outline", query: "(3dexpprd:#all)", refineValue: null },
  { name: "Project", icon: "mdi-briefcase-outline", query: "Project", refineValue: "Project Space" },
  { name: "Program", icon: "mdi-calendar-check-outline", query: "(3dexpProgram:#all)", refineValue: "Program" },
  { name: "Document", icon: "mdi-file-document-outline", query: "(3dexpDOC:#all)", refineValue: "Document" },
  { name: "Task", icon: "mdi-clipboard-check-outline", query: "(3dexptsk:#all)", refineValue: "Task" },
  { name: "Change Action", icon: "mdi-file-edit-outline", query: "(3dexpca:#all)", refineValue: "Change Action" },
  { name: "Risk", icon: "mdi-shield-alert-outline", query: "Risk", refineValue: "Risk" },
  { name: "Requirement", icon: "mdi-format-list-checks", query: "(3dexpreq:#all)", refineValue: "Requirement" },
  { name: "Raw Material", icon: "mdi-package-variant-closed", query: "(3dexpRaw_Material:#all)", refineValue: "Raw Material" },
  { name: "Issue", icon: "mdi-alert-circle-outline", query: "(3dexpiss:#all)", refineValue: "Issue" },
];

// Holds state shared by several components (TypeSelectionView, DashboardView,
// App.vue) so it only needs to be defined/changed in one place instead of
// being duplicated or passed around via props/emits.
export const useDashboardStore = defineStore("dashboard", {
  state: () => ({
    type: DEFAULT_TYPE,
    customForm: null,
    typeConfig: [], // [{name, icon, query, refineValue}, ...] fetched from backend
    viewSettings: { ...DEFAULT_VIEW_SETTINGS },
    user: {
      firstName: "",
      lastName: "",
      name: "",
      email: "",
      login: "",
    },
    baseUrl: "",
    Space3DURL: "",
    Server: "",
  }),
  actions: {
    setType(type) {
      this.type = type;
    },
    setViewSettings(settings) {
      this.viewSettings = { ...settings };
    },
    setValue(key, value) {
      this[key] = value;
    },
    async fetchTypeConfig() {
      try {
        const data = await typeConfigApi.getTypeConfig();
        this.typeConfig = data && data.length ? data : FALLBACK_TYPE_CONFIG;
      } catch (e) {
        this.typeConfig = FALLBACK_TYPE_CONFIG;
      }
    },
    setCustomForm(form) {
      this.customForm = form;
    },
  },
  getters: {
    getType: (state) => state.type,
    // {name, icon} pairs for TypeSelectionView
    getTypeOptions: (state) => state.typeConfig.map(({ name, icon }) => ({ name, icon })),
    getTypeConfig: (state) => state.typeConfig,
    getViewSettings: (state) => state.viewSettings,
    getUser: (state) => state.user,
    getBaseUrl: (state) => state.baseUrl,
    getSpace3DURL: (state) => state.Space3DURL,
    getServer: (state) => state.Server,
  },
});